from pathlib import Path
r=Path('projects/minecraft-cases')
css='''
body.page-case .case-grid{display:none}.case-play{background:radial-gradient(ellipse at top,#34254f,#151522 68%);border:1px solid #48405d;border-radius:20px;padding:24px;margin:15px 0 30px;text-align:center}.case-play h3{font:800 27px Unbounded,sans-serif}.play-art{width:190px;height:165px;object-fit:contain}.play-controls{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin:16px}.play-count{background:#222135;border:1px solid #53466a;border-radius:10px;padding:11px 15px;color:white;cursor:pointer}.play-count.active{border-color:#ad81ff;background:#483061}.play-submit{min-height:48px;min-width:200px}.play-status{min-height:25px;color:#bbb}.roll-stack{display:grid;gap:9px;max-width:860px;margin:16px auto}.roll-lane{position:relative;overflow:hidden;border:1px solid #514667;border-radius:12px;background:#131420;height:100px}.roll-lane:after{content:'';position:absolute;left:50%;top:0;bottom:0;width:3px;background:#91e985;box-shadow:0 0 10px #91e985}.roll-strip{display:flex;width:max-content;height:100%;align-items:center}.roll-tile{width:92px;height:86px;flex:none;display:grid;justify-items:center;align-content:center;gap:2px;border-right:1px solid #312d41;font-size:10px;color:#bbb}.roll-tile img{width:53px;height:53px;object-fit:contain}.roll-wins{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;max-width:850px;margin:16px auto}.roll-win{border:1px solid #a47ddb;background:#242036;border-radius:12px;padding:12px;display:grid;justify-items:center;gap:6px;font-size:12px;overflow-wrap:anywhere}.roll-win img{width:75px;height:70px;object-fit:contain}body.page-upgrades .upgrade-layout{grid-template-columns:repeat(2,minmax(0,1fr))}body.page-upgrades .upgrade-center{grid-row:1;grid-column:1/-1;flex-direction:column;text-align:center;background:radial-gradient(circle at top,#34254e,#171622 65%)}body.page-upgrades .chance{width:205px;height:205px;flex:0 0 205px;background:conic-gradient(#85db78 var(--chance,0%),#343240 0)}body.page-upgrades .chance:before{inset:15px}body.page-upgrades .chance b{font-size:32px}body.page-upgrades .up-info{flex:none}body.page-upgrades .up-info p{max-width:550px}body.page-upgrades .picker{flex-wrap:wrap;max-height:230px;overflow:auto}body.page-upgrades .upgrade-panel{min-width:0}@media(max-width:680px){.case-play{padding:15px 8px}.play-art{height:135px}.play-count{padding:10px 12px}.roll-tile{width:74px}body.page-upgrades .upgrade-layout{grid-template-columns:minmax(0,1fr)}body.page-upgrades .upgrade-center{grid-row:auto;grid-column:1;order:-1}body.page-upgrades .chance{width:165px;height:165px;flex-basis:165px}body.page-upgrades .picker{max-height:150px}}
'''
js='''
if(document.body.dataset.case){const c=cases.find(x=>x.id===document.body.dataset.case),section=$('#cases');if(c){const art=A+(['holyworld','reallyworld','clients','spooky','monthly'].includes(c.id)?'ref-case-'+c.id+'.webp':'case-'+c.id+'.svg');const box=document.createElement('div');box.className='case-play';box.innerHTML=`<h3>${c.name}</h3><img class="play-art" src="${art}" alt="Кейс ${c.name}"><p>Выбери количество · один кейс ✦ ${format(c.price)}</p><div class="play-controls" role="group" aria-label="Количество кейсов">${[1,2,3,5,10].map(n=>`<button class="play-count ${n===1?'active':''}" data-amount="${n}" aria-pressed="${n===1}">${n}</button>`).join('')}</div><button class="btn btn-primary play-submit" id="playOpen">Открыть</button><p class="play-status" id="playStatus" role="status" aria-live="polite">Результат появится здесь, без всплывающего окна.</p><div class="roll-stack" id="rollStack"></div><div class="roll-wins" id="rollWins"></div>`;section.insertBefore(box,section.querySelector('.case-detail'));let amount=1;const go=$('#playOpen'),status=$('#playStatus');function updatePlay(){go.textContent=`Открыть ${amount} · ✦ ${format(c.price*amount)}`;go.disabled=busy||state.balance<c.price*amount;go.title=go.disabled&&!busy?'Недостаточно демо-монет':''}box.querySelector('.play-controls').addEventListener('click',e=>{let b=e.target.closest('[data-amount]');if(!b||busy)return;amount=Number(b.dataset.amount);box.querySelectorAll('[data-amount]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});updatePlay()});go.addEventListener('click',()=>{if(busy)return;const count=amount,total=c.price*count;if(state.balance<total){notify('Недостаточно демо-монет');return}busy=true;state.balance-=total;save();render();updatePlay();$('#rollWins').replaceChildren();const stack=$('#rollStack');stack.replaceChildren();status.textContent='Кейсы открываются…';const wins=Array.from({length:count},()=>chooseDrop(c)),rows=[];for(let j=0;j<count;j++){let lane=document.createElement('div');lane.className='roll-lane';let strip=document.createElement('div');strip.className='roll-strip';let pool=c.drops.map(([id])=>P[id]);let seq=Array.from({length:27},()=>pool[Math.floor(Math.random()*pool.length)]);seq[21]=wins[j];strip.innerHTML=seq.map(p=>`<div class="roll-tile"><img src="${itemImage(p)}" alt=""><span>${p.name.split(' · ').at(-1).slice(0,12)}</span></div>`).join('');lane.append(strip);stack.append(lane);rows.push([lane,strip])}requestAnimationFrame(()=>requestAnimationFrame(()=>rows.forEach(([lane,strip],j)=>{let w=strip.firstElementChild.getBoundingClientRect().width;strip.style.transition=`transform ${3.1+j*.1}s cubic-bezier(.12,.68,.14,1)`;strip.style.transform=`translateX(-${21*w+w/2-lane.clientWidth/2}px)`})));setTimeout(()=>{wins.forEach(p=>state.inventory.push({id:p.id,uid:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)}));save();busy=false;render();updatePlay();status.textContent=`Открыто: ${count}. Дроп добавлен в профиль.`;$('#rollWins').innerHTML=wins.map(p=>`<div class="roll-win"><img src="${itemImage(p)}" alt=""><strong>${p.name}</strong><small>✦ ${format(p.value)}</small></div>`).join('');notify('Открыто кейсов: '+count)},4400)});updatePlay();const old=section.querySelector('#caseGrid [data-case]');if(old)old.remove()}}
'''
for p in r.glob('*.html'):
 s=p.read_text()
 if 'const cases=' not in s or '/* INLINE ROLLS */' in s:continue
 s=s.replace('</style>','/* INLINE ROLLS */'+css+'</style>',1).replace('})();\n</script>',js+'})();\n</script>',1)
 p.write_text(s)
print('updated')
